design_text:
{
  "site_summary": "A shaded patio microclimate designed for a curious dog who loves to graze safely.",
  "layout_strategy": "Trailing prayer plants on elevated plant stands at eye level, upright architectural foliage plants at mid height against the back wall, and low-growing ferns and herbs along the floor edge forming a pet-accessible grazing layer.",
  "combination_logic": "This combination pairs the bold vertical striping of Calathea insignis with the delicate fronds of Asplenium bulbiferum and the architectural broad leaves of Aspidistra elatior, creating a rich tapestry of deep greens and purple undersides that thrive together in shade and provide year-round textural contrast.",
  "zones": [
    {
      "zone_name": "Elevated Canopy Zone",
      "zone_role": "hanging",
      "layer": "vertical",
      "placement": "On the east-facing hanging brackets, 3 hours of morning sun, sheltered from afternoon heat.",
      "plants": [
        {
          "scientific_name": "Calathea insignis",
          "common_name": "Prayer Plant",
          "why": "Fits the elevated zone with its striking upward and outward growth habit.",
          "role_in_combination": "Provides dramatic leaf shape, purple undersides, and dynamic movement as leaves fold at night."
        },
        {
          "scientific_name": "Aphelandra squarrosa",
          "common_name": "Saffron Spike Zebra",
          "why": "Thrives in bright indirect light at vertical levels.",
          "role_in_combination": "Contributes glossy veined foliage and bright yellow flower spikes for seasonal accent."
        }
      ],
      "maintenance": [
        "Water thoroughly when the top inch of soil feels dry.",
        "Mist foliage weekly to maintain humidity.",
        "Prune away yellowing lower leaves in spring."
      ]
    },
    {
      "zone_name": "Backdrop Foliage Zone",
      "zone_role": "screening",
      "layer": "mid",
      "placement": "Against the north-facing wall, indirect light all day, protected from wind.",
      "plants": [
        {
          "scientific_name": "Aspidistra elatior",
          "common_name": "Cast Iron Plant",
          "why": "Extremely robust mid-layer plant that handles deep shade against the wall.",
          "role_in_combination": "Acts as the structural anchor with broad, dark green, leathery leaves."
        },
        {
          "scientific_name": "Ageratina altissima",
          "common_name": "White Snakeroot",
          "why": "Adds height and fullness to the mid-height wall containers.",
          "role_in_combination": "Brings upright perrennial form and delicate white flower clusters in late summer."
        }
      ],
      "maintenance": [
        "Water moderately, allowing soil to dry slightly between waterings.",
        "Wipe dust from broad leaves monthly in spring and summer.",
        "Divide congested roots every two years in spring."
      ]
    },
    {
      "zone_name": "Pet Grazing Edge",
      "zone_role": "grazing",
      "layer": "ground",
      "placement": "Along the patio floor edge, full shade, fully accessible to the dog.",
      "plants": [
        {
          "scientific_name": "Asplenium bulbiferum",
          "common_name": "Hen and Chickens Fern",
          "why": "Soft fronds are completely safe and engaging for the pet to sniff and brush against.",
          "role_in_combination": "Provides fine feathery texture and delicate contrast against the coarser foliage above."
        },
        {
          "scientific_name": "Anethum graveolena",
          "common_name": "Dill",
          "why": "Provides aromatic stimulation at ground level within reach of the dog.",
          "role_in_combination": "Adds feathery, aromatic foliage that contrasts in texture and scent with the fern."
        }
      ],
      "maintenance": [
        "Keep soil consistently moist but never waterlogged.",
        "Check daily in summer to ensure the ground layer does not dry out.",
        "Trim back spent herb stems at the end of autumn."
      ]
    }
  ],
  "care_instructions": [
    {
      "task": "Water the elevated Prayer Plant and Saffron Spike containers",
      "frequency": "Twice a week in summer, weekly in spring and autumn",
      "season": "Summer"
    },
    {
      "task": "Check moisture levels of the ground grazing layer",
      "frequency": "Every other day during dry spells",
      "season": "Summer"
    },
    {
      "task": "Inspect foliage for dust and wipe Aspidistra elatior leaves",
      "frequency": "Monthly",
      "season": "Spring"
    }
  ],
  "care_cautions": [
    "Overwatering the hanging Calathea insignis baskets can lead to root rot.",
    "The ground grazing layer containing Asplenium bulbiferum must be monitored so the dog does not dig up the rootballs.",
    "Tender perennials like Aphelandra squarrosa must be protected from sudden frost drops in autumn."
  ],
  "pet_safety_note": "Every plant selected is 100% non-toxic to cats and dogs, and the designated grazing zone allows safe interaction at ground level."
}
